import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential


def _get_field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in (
        "value_string",
        "value_currency",
        "value_number",
        "value_date",
        "value_time",
        "value_phone_number",
        "value_integer",
        "value_selection_mark",
        "value_signature",
        "content",
        "value",
    ):
        if hasattr(field, attr):
            value = getattr(field, attr)
            if value is not None:
                if attr == "value_currency":
                    amount = getattr(value, "amount", None)
                    currency_symbol = getattr(value, "currency_symbol", None)
                    currency_code = getattr(value, "currency_code", None)
                    return {
                        "amount": amount,
                        "currency_symbol": currency_symbol,
                        "currency_code": currency_code,
                    }
                return value
    return None


def _currency_amount(field: Any) -> Optional[float]:
    if field is None:
        return None
    value_currency = getattr(field, "value_currency", None)
    if value_currency is not None:
        return getattr(value_currency, "amount", None)
    value_number = getattr(field, "value_number", None)
    if value_number is not None:
        return float(value_number)
    value_integer = getattr(field, "value_integer", None)
    if value_integer is not None:
        return float(value_integer)
    return None


def _parse_items(items_field: Any) -> List[Dict[str, Any]]:
    if items_field is None:
        return []

    value_array = getattr(items_field, "value_array", None)
    if not value_array:
        return []

    parsed_items: List[Dict[str, Any]] = []
    for item in value_array:
        item_obj = getattr(item, "value_object", None) or {}
        parsed_items.append(
            {
                "description": _get_field_value(item_obj.get("Description")),
                "quantity": _currency_amount(item_obj.get("Quantity")),
                "price": _currency_amount(item_obj.get("Price")),
                "total_price": _currency_amount(item_obj.get("TotalPrice")),
            }
        )
    return parsed_items


def extract_receipt_data(receipt_bytes: bytes) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    api_key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    poller = client.begin_analyze_document(
        model_id="prebuilt-receipt",
        body=AnalyzeDocumentRequest(bytes_source=receipt_bytes),
    )
    result = poller.result()

    if not result.documents:
        return {
            "merchant": None,
            "tax": None,
            "total": None,
            "items": [],
        }

    doc = result.documents[0]
    fields = doc.fields or {}

    merchant = _get_field_value(fields.get("MerchantName"))
    tax = _currency_amount(fields.get("Tax"))
    total = _currency_amount(fields.get("Total"))
    items = _parse_items(fields.get("Items"))

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
